#!/usr/bin/env node
'use strict';
// Writes each copied skill's NOTICE.md: node scripts/vendor/notice.js [root]
// Built from vendor.lock.json and the licence area only, so the same lock and
// licences always give the same bytes; the collection check fails on any
// NOTICE.md that differs from a fresh generation (#77, owner answer 1).

const fs = require('fs');
const path = require('path');
const lock = require('./lock');

// Every generated NOTICE.md opens with this, so the check can tell a
// generated copy notice from a hand-written one for an adapted skill.
const GENERATED = '<!-- Generated by scripts/vendor/notice.js';

// The NOTICE.md text for one lock entry and its source's licence text.
function renderNotice(e, licenceText) {
  const licence = licenceText.replace(/\s+$/, '') + '\n';
  const longest = Math.max(2, ...(licence.match(/`+/g) || []).map((r) => r.length));
  const fence = '`'.repeat(longest + 1);
  const tree = 'https://github.com/' + e.source + '/tree/' + e.sha + '/' + e.path;
  return [
    GENERATED + ' from vendor.lock.json and ' + lock.licenceFile(e) + '. Do not edit. -->',
    '',
    '# Notice',
    '',
    'This skill is copied from [' + e.source + '](' + tree + '), under the licence below.',
    '',
    '- Source repository: https://github.com/' + e.source,
    '- Path: `' + e.path + '`',
    '- Pinned commit: `' + e.sha + '`',
    '- Licence: ' + e.license,
    '- Local changes: ' + e.changes,
    '',
    '## Licence',
    '',
    fence + 'text',
    licence + fence,
    '',
  ].join('\n');
}

function main() {
  const root = path.resolve(process.argv[2] || path.join(__dirname, '..', '..'));
  const { exists, entries, errors } = lock.read(root);
  if (!exists) { console.log('no ' + lock.LOCK + ': nothing to write'); return 0; }
  if (errors.length) {
    for (const m of errors) console.log('FAIL ' + lock.LOCK + ' ' + m);
    return 1;
  }
  let failed = 0;
  for (const e of entries) {
    let licence;
    try { licence = fs.readFileSync(path.join(root, e.licence), 'utf8'); } catch (err) {
      console.log('FAIL ' + e.notice + ': no licence file ' + e.licence);
      failed++;
      continue;
    }
    if (!fs.existsSync(path.join(root, e.skill))) {
      console.log('FAIL ' + e.notice + ': no skill folder ' + e.skill);
      failed++;
      continue;
    }
    const file = path.join(root, e.notice);
    const text = renderNotice(e, licence);
    const old = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (old === text) continue;
    fs.writeFileSync(file, text);
    console.log((old === null ? 'wrote ' : 'updated ') + e.notice);
  }
  return failed ? 1 : 0;
}

if (require.main === module) process.exit(main());

module.exports = { renderNotice, GENERATED };
